import type { MetadataRoute } from "next";

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "ReCopyFast - Edit your website copy in place",
    short_name: "ReCopyFast",
    description:
      "Make the copy on the site you already built editable, with one script tag.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#ffffff",
    theme_color: "#2563eb",
    // Generated by `src/app/icon.tsx`. Chrome requires both a 192px and a
    // 512px icon before it will offer to install the app.
    icons: [
      {
        src: "/icon/192",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icon/512",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
    ],
  };
}
